+  INSTANTIATE_GDN_DECODE_16BIT(StateT, 2)           \
+  INSTANTIATE_GDN_DECODE_16BIT(StateT, 3)           \
+  INSTANTIATE_GDN_DECODE_16BIT(StateT, 4)           \
